{
  "lignes": [
    {
      "nom": "Lamine Yamal",
      "justification": "Il termine premier grâce à des statistiques exceptionnelles en buts et passes décisives combinées à la victoire en Coupe du Monde et en Liga."
    },
    {
      "nom": "Harry Kane",
      "justification": "Il prend la deuxième place grâce à un total impressionnant de 61 buts et un triplé national avec le Bayern."
    },
    {
      "nom": "Kylian Mbappé",
      "justification": "Il se classe troisième avec 42 buts marqués malgré une saison sans titre collectif."
    },
    {
      "nom": "Michael Olisé",
      "justification": "Il occupe la quatrième place en raison de son rôle clé dans le triplé du Bayern, notamment avec 26 passes décisives."
    },
    {
      "nom": "Khvicha Kvaratskhelia",
      "justification": "Il est cinquième grâce à sa contribution majeure dans le quintuplé historique du Paris Saint-Germain."
    },
    {
      "nom": "Ousmane Dembélé",
      "justification": "Il est sixième après avoir remporté le quintuplé avec le PSG et affiché de solides statistiques."
    },
    {
      "nom": "Pedri",
      "justification": "Il ferme la marche à la septième place malgré la Coupe du Monde et la Liga, en raison d'un total de buts plus faible."
    }
  ]
}
